    <div class="admin-grid"><section class="card wide"><div class="section-heading"><div><p class="eyebrow">WEEKLY CALENDAR</p><h2>Course and exam schedule</h2></div><span class="muted">Drag an event to another day or time (15-minute increments).</span></div><?php $weekStart = new \DateTimeImmutable('monday this week'); ?><div class="time-calendar" data-class-id="<?= $class['id'] ?>" data-csrf="<?= h(\App\Core\Csrf::token()) ?>"><div class="time-scale"><?php for ($hour = 8; $hour <= 18; $hour++): ?><span><?= sprintf('%02d:00', $hour) ?></span><?php endfor; ?></div><div class="time-days"><?php for ($offset = 0; $offset < 7; $offset++): ?><?php $day = $weekStart->modify("+{$offset} days"); $date = $day->format('Y-m-d'); ?><div class="time-day"><header><strong><?= h($day->format('D')) ?></strong><span><?= h($day->format('d M')) ?></span></header><div class="time-day-body" data-date="<?= $date ?>"><?php foreach ($calendarWeek as $event): ?><?php if ($event['event_date'] !== $date) continue; $start = explode(':', $event['start_time']); $end = explode(':', $event['end_time']); $top = max(0, (((int) $start[0] * 60 + (int) $start[1]) - 480); $height = max(28, (((int) $end[0] * 60 + (int) $end[1]) - ((int) $start[0] * 60 + (int) $start[1])); $eventId = $event['event_type'] === 'EXAM' ? $event['exam_id'] : $event['schedule_slot_id']; ?><button class="time-event <?= $event['event_type'] === 'EXAM' ? 'exam' : '' ?>" type="button" draggable="true" style="top:<?= $top ?>px;height:<?= $height ?>px" data-event-type="<?= $event['event_type'] ?>" data-event-id="<?= $eventId ?>" data-occurrence-date="<?= h($event['occurrence_date']) ?>" data-duration="<?= $height ?>" data-modal-open="<?= $event['event_type'] === 'EXAM' ? 'edit-exam-' . $event['exam_id'] : 'edit-course-' . $event['course_id'] ?>"><small><?= h(substr((string) $event['start_time'], 0, 5)) ?>?<?= h(substr((string) $event['end_time'], 0, 5)) ?></small><strong data-no-translate><?= h($event['course_title']) ?></strong><span><?= h($event['event_type']) ?></span></button><?php endforeach; ?></div></div><?php endfor; ?></div></div></section>
