    <?php foreach ($courses as $course): ?><?php $slots = []; foreach (($courseSlots[$course['id']] ?? []) as $slot) $slots[$slot['weekday']] = $slot; ?><div class="modal" id="edit-course-<?= $course['id'] ?>" role="dialog" aria-modal="true"><section class="modal-panel modal-panel-large"><button class="modal-close" type="button" data-modal-close aria-label="Close">?</button><p class="eyebrow">COURSE SCHEDULE</p><h2 data-no-translate><?= h($course['title']) ?></h2><form method="post" action="/admin/courses/schedule"><?= \App\Core\Csrf::field() ?><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><div class="admin-grid"><label>Course starts <input name="start_date" type="date" value="<?= h($course['start_date']) ?>" required></label><label>Course ends <input name="end_date" type="date" value="<?= h($course['end_date']) ?>" required></label><label>Status <select name="status"><option value="DRAFT" <?= $course['status'] === 'DRAFT' ? 'selected' : '' ?>>Draft</option><option value="PUBLISHED" <?= $course['status'] === 'PUBLISHED' ? 'selected' : '' ?>>Published</option></select></label></div><div class="schedule-picker"><?php foreach (['MONDAY'=>'Monday','TUESDAY'=>'Tuesday','WEDNESDAY'=>'Wednesday','THURSDAY'=>'Thursday','FRIDAY'=>'Friday','SATURDAY'=>'Saturday','SUNDAY'=>'Sunday'] as $day=>$label): ?><?php $slot=$slots[$day]??null; ?><label class="schedule-row"><input type="checkbox" name="schedule_days[]" value="<?= $day ?>" data-schedule-toggle="<?= $course['id'] ?>-<?= $day ?>" <?= $slot?'checked':'' ?>><strong><?= $label ?></strong><span>From <input type="time" name="schedule_start[<?= $day ?>]" value="<?= h($slot?substr($slot['start_time'],0,5):'08:00') ?>" <?= $slot?'':'disabled' ?> data-schedule-time="<?= $course['id'] ?>-<?= $day ?>"></span><span>To <input type="time" name="schedule_end[<?= $day ?>]" value="<?= h($slot?substr($slot['end_time'],0,5):'10:00') ?>" <?= $slot?'':'disabled' ?> data-schedule-time="<?= $course['id'] ?>-<?= $day ?>"></span></label><?php endforeach; ?></div><button>Save course schedule</button></form><form method="post" action="/admin/courses/cancel"><?= \App\Core\Csrf::field() ?><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><button class="danger">Cancel course</button></form></section></div><?php endforeach; ?>
