<script>
document.querySelectorAll('.time-event').forEach((event) => { event.addEventListener('dragstart', (e) => { e.dataTransfer.setData('text/plain', JSON.stringify({type:event.dataset.eventType,id:event.dataset.eventId,occurrence:event.dataset.occurrenceDate,duration:+event.dataset.duration})); e.dataTransfer.effectAllowed='move'; event.dataset.dragging='1'; }); event.addEventListener('dragend', () => delete event.dataset.dragging); });
document.querySelectorAll('.time-day-body').forEach((day) => { day.addEventListener('dragover', (e) => e.preventDefault()); day.addEventListener('drop', (e) => { e.preventDefault(); const data=JSON.parse(e.dataTransfer.getData('text/plain')); const rect=day.getBoundingClientRect(); let minutes=Math.round((((e.clientY-rect.top)/rect.height)*600)/15)*15; minutes=Math.max(0,Math.min(585,minutes)); const start=`${String(8+Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`; const calendar=day.closest('.time-calendar'); const form=document.createElement('form'); form.method='post'; form.action='<?= h(\App\Core\Request::basePath()) ?>/admin/calendar/move'; [['class_id',calendar.dataset.classId],['_token',calendar.dataset.csrf],['event_type',data.type],['event_id',data.id],['occurrence_date',data.occurrence],['event_date',day.dataset.date],['start_time',start]].forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.append(input);}); document.body.append(form); form.submit(); }); });
</script>

