<script>
document.querySelectorAll('[data-schedule-toggle]').forEach((toggle) => toggle.addEventListener('change', () => {
    document.querySelectorAll(`[data-schedule-time="${toggle.dataset.scheduleToggle}"]`).forEach((input) => input.disabled = !toggle.checked);
}));
</script>
